<script setup>
import { useForm } from '@inertiajs/vue3'; import AdminLayout from '../../Layouts/AdminLayout.vue';
const props=defineProps({settings:Object}); const form=useForm({settings:{...props.settings}}); const ensure=key=>{if(form.settings[key]===undefined)form.settings[key]=''}; ['site_name','facebook_url','instagram_url','email','seo_default_title','seo_default_description','seo_keywords','seo_og_image','twitter_handle','google_site_verification'].forEach(ensure); const submit=()=>form.put('/admin/settings');
</script>
<template><AdminLayout><p class="text-xs uppercase tracking-widest text-[#c56b4d]">SITE CONFIGURATION</p><h1 class="mt-2 font-serif text-4xl">Settings</h1><form @submit.prevent="submit" class="mt-8 max-w-3xl space-y-8"><section class="rounded-2xl bg-white p-7"><h2 class="font-serif text-2xl">General</h2><div class="mt-5 grid gap-5 md:grid-cols-2"><label>Site name<input v-model="form.settings.site_name" class="field" /></label><label>Contact email<input v-model="form.settings.email" type="email" class="field" /></label><label>Facebook URL<input v-model="form.settings.facebook_url" type="url" class="field" /></label><label>Instagram URL<input v-model="form.settings.instagram_url" type="url" class="field" /></label><label>Twitter handle<input v-model="form.settings.twitter_handle" placeholder="@yourhandle" class="field" /></label></div></section><section class="rounded-2xl bg-white p-7"><h2 class="font-serif text-2xl">Search engine optimization</h2><p class="mt-2 text-sm text-[#718079]">These defaults are used across pages that do not define their own metadata.</p><div class="mt-5 space-y-5"><label>Default SEO title<input v-model="form.settings.seo_default_title" class="field" maxlength="60" /></label><label>Default description<textarea v-model="form.settings.seo_default_description" rows="4" maxlength="160" class="field" /></label><label>Keywords<input v-model="form.settings.seo_keywords" placeholder="author, books, literature" class="field" /></label><label>Open Graph image URL<input v-model="form.settings.seo_og_image" type="url" placeholder="https://example.com/og-image.jpg" class="field" /></label><label>Google site verification<input v-model="form.settings.google_site_verification" class="field" /></label></div></section><button :disabled="form.processing" class="rounded-full bg-[#1d4843] px-7 py-3 font-semibold text-white">Save settings</button></form></AdminLayout></template><style scoped>.field{display:block;margin-top:.5rem;width:100%;border:0;border-radius:.5rem;background:#f7f5f0;padding:.75rem 1rem;box-shadow:inset 0 0 0 1px #dfe1d8;outline:none}.field:focus{box-shadow:inset 0 0 0 2px #c56b4d}label{display:block;font-size:.875rem;color:#49605c}</style>
